import { border, colors, duration, easing, radius, shadow, space, typography } from "./tokens.js";
function splitFontStack(stack) {
    return stack
        .split(",")
        .map((part) => part.trim().replace(/^'|'$/g, ""))
        .filter(Boolean);
}
function toTailwindFontSize() {
    return Object.fromEntries(Object.entries(typography.size).map(([key, token]) => [
        key,
        [
            token.value,
            {
                lineHeight: token.leading,
                letterSpacing: token.tracking
            }
        ]
    ]));
}
export const avoro = {
    theme: {
        extend: {
            colors,
            fontFamily: {
                display: splitFontStack(typography.family.display),
                sans: splitFontStack(typography.family.sans),
                mono: splitFontStack(typography.family.mono)
            },
            fontSize: toTailwindFontSize(),
            fontWeight: typography.weight,
            spacing: space,
            borderRadius: radius,
            borderWidth: border,
            boxShadow: shadow,
            transitionDuration: duration,
            transitionTimingFunction: easing
        }
    }
};
export default avoro;
